        "type": "checkbox",
        "label": "Enable Filter"
      }
    }
  ],
  [
          {
         "fieldName": "ucinn_ascendv2__Table_Object_Search_Filter_Info_List__c",
         "toolTip": "JSON list of object filter search information. \n EX) [{ \"label\":\"label Value\", \"objectApi\":\"ObjectApiNameValue\", \"referenceApi\":\"field That Looks up to search object or null to signify it is the search object\", \"fieldsToQuery\": [\"fieldl1\", \"field2\",\"etc\"], \"defaultWhereClause\": \"Stage == 'Active'\", \"allowFilter\" : true, \"displayTab\" : false, \"limit\":\"49000\", \"orderByField\":\"Id\", \"orderByDirection\":\"ASC\"}]",
         "jsonFieldParams": {
            "label": "Table Object Search Filter Info List",
            "type": "list",
            "listType": "object",
            "helpText": "JSON list of object filter search information. EX) [{ \"label\":\"label Value\", \"objectApi\":\"ObjectApiNameValue\", \"referenceApi\":\"field That Looks up to search object or null to signify it is the search object\", \"fieldsToQuery\": [\"feidl1\", \"field2\",\"etc\"], \"defaultWhereClause\": \"Stage == 'Active'\", \"allowFilter\" : true, \"displayTab\" : false, \"limit\":\"49000\", \"orderByField\":\"Id\", \"orderByDirection\":\"ASC\"}]",
            "jsonKeysToValueList": [
               {
                  "key": "label",
                  "label": "Label",
                  "valueCustomFieldParams": {
                     "type": "text"
                  }
               },
               {
                  "key": "objectApi",
                  "label": "Object Api Name",
                  "required":true,
                  "helpText": "Object Api Name that we are searching against. It can be the object we are querying for or a child related object of the main object we are querying for.",
                  "valueCustomFieldParams": {
                     "type": "text"
                  }
               },
               {
                  "key": "referenceApi",
                  "label": "Reference Field Api Name",
                  "helpText": "The lookup field to the object being queried. Leave blank if this is the object that is being queried.",
                  "valueCustomFieldParams": {
                     "type": "text"
                  }
               },
               {
                  "key": "allowFilter",
                  "label": "Allow Filter",
                  "helpText": "Allow users to filter against this object when querying for the main object.",
                  "valueCustomFieldParams": {
                     "type": "checkbox"
                  }
               },
               {
                  "key": "limit",
                  "label": "Limit",
                  "helpText": "Amount of records to query.",
                  "valueCustomFieldParams": {
                     "type": "text"
                  }
               },
               {
                  "key": "orderBy",
                  "label": "Order By",
                  "helpText": "SOQL order by statment of how you want the records to be returned.",
                  "valueCustomFieldParams": {
                     "type": "text"
                  }
               },
               {
                  "key": "defaultWhereClause",
                  "label": "Where Clause",
                  "helpText": "SOQL Default where clause that will always be appended with your filter when searching for records.",
                  "valueCustomFieldParams": {
                     "type": "textarea"
                  }
               },
               {
                  "key": "displayTab",
                  "label": "Display Tab",
                  "helpText": "When there is more than one object to filter by we have the option to display the tabs of the different objects to filter by.",
                  "valueCustomFieldParams": {
                     "type": "checkbox"
                  }
               },
               {
                  "key": "fieldsToQuery",
                  "label": "Fields To Query",
                  "helpText": "List of Fields To Query. Only applicable for the Object being queried not the related children records.",
                  "valueJsonFieldParams": {
                     "type": "list",
                     "listType": "value",
                     "valueCustomFieldParams": {
                        "type": "text"
                     }
                  }
               }
            ]
         }
      }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Fields_To_Display__c",
      "toolTip":"Field Api Names of the fields you want to display, order of field defined determines order in which fields are displayed.",
      "jsonFieldParams": {
        "label": "Fields To Display",
        "type": "list",
        "listType": "value",
        "allowReorder": true,
        "helpText": "Field Api Names of the fields you want to display, order of field defined determines order in which fields are displayed.",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Headers__c",
      "toolTip":"Header Labels that correspond to the Fields to Display. If nothing populated it will just use the field labels defined on the fields.",
      "jsonFieldParams": {
        "label": "Headers",
        "type": "list",
        "listType": "value",
        "allowReorder": true,
        "helpText": "Header Labels that correspond to the Fields to Display. If nothing populated it will just use the field labels defined on the fields.",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Field_Type_Dict__c",
        "toolTip": "Configuration to determine how we should show the fields to display.",
      "jsonFieldParams": {
        "label": "Field Type Dict",
        "type": "object",
        "helpText": "Configuration to determine how we should show the fields to display.",
        "keyLabel":"Field Api Name",
        "valueLabel":"Display Type",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Id",
                "REFERENCE",
                "REFERENCE-URL",
                "REFERENCE-READONLY",
                "READONLY",
                "EMAIL",
                "PHONE",
                "DATE",
                "DATETIME",
                "INTEGER",
                "DOUBLE",
                "BOOLEAN",
                "STRING",
                "URL",
                "CURRENCY",
                "CURRENCY-READONLY",
                "DATE-READONLY",
                "DATETIME-READONLY",
                "NUMBER-READONLY",
                "PERCENTAGE-READONLY",
                "PHONE-READONLY",
                "RICHTEXT-READONLY",
                "URL-READONLY",
                "TEXTAREA-READONLY",
                "BOOLEAN-READONLY",
                "UNESCAPED-HTML",
                "Compound-Address",
                "ADDRESS-READONLY",
                "PICKLIST-READONLY",
                "MULTIPICKLIST-READONLY",
                "TIME-READONLY",
                "GEOLOCATION-READONLY",
                "ENCRYPTED-READONLY"
              ]
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK1"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Filter_Criteria_Opportunity__c",
      "toolTip":"It should be written as if it were to follow a WHERE from a SOQL query. For example, Amount > 10.",
      "customFieldParams": {
        "type": "textarea",
        "label": "Filter Criteria (Opportunity)"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Filter_Criteria_Designation_Detail__c",
      "toolTip":"It should be written as if it were to follow a WHERE from a SOQL query. For example, Amount > 10.",
      "customFieldParams": {
        "type": "textarea",
        "label": "Filter Criteria (Designation Detail)"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Other_Object_Name__c",
      "toolTip":"Object to search for in place of Opportunity",
      "customFieldParams": {
        "type": "text",
        "label": "Other Object Name"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Other_Filter_Criteria__c",
      "toolTip":"Filter criteria for specified other object",
      "customFieldParams": {
        "type": "textarea",
        "label": "Other Filter Criteria"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Order_By__c",
      "toolTip":"Only one column may be specified and it should be the Field API Name of the value being displayed in the column. No namespace is needed.",
      "customFieldParams": {
        "type": "text",
        "label": "Order By"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Order_by_Direction__c",
      "toolTip":"The value can either by ASC or DESC.",
      "customFieldParams": {
        "type": "text",
        "label": "Order By Direction"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Number_of_Records_Per_Page__c",
      "customFieldParams": {
        "type": "picklist",
        "label": "Number of Records Per Page",
        "customPicklistValuesString": [
          "5",
          "10",
          "25"
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Record_Type_Name__c",
      "customFieldParams": {
        "type": "text",
        "label": "Record Type Name"
      }
    }
  ]
]
